import type { BuffConfig } from '@/types/buff'
import type { Character } from '@/types/character'
import { BuffSystem } from '@/core/BuffSystem'

/**
 * Buff上下文类
 * 为Buff实例提供运行环境和上下文信息
 * 包含Buff的配置、状态、变量管理等功能
 * 支持对象池复用
 */
export class BuffContext {
  /** 角色ID */
  public characterId: string = ''
  /** Buff实例ID */
  public instanceId: string = ''
  /** Buff配置信息 */
  public config: BuffConfig = {} as BuffConfig
  /** Buff开始时间戳 */
  public startTime: number = 0
  /** 变量映射，用于存储Buff运行时的临时数据 */
  public variables = new Map<string, any>()
  /** Buff系统实例（通过容器或构造函数注入） */
  private _buffSystem: any = null

  /**
   * 构造函数
   * @param characterId 角色ID
   * @param instanceId Buff实例ID
   * @param config Buff配置信息
   * @param buffSystem Buff系统实例（可选，用于依赖注入）
   */
  constructor(characterId?: string, instanceId?: string, config?: BuffConfig, buffSystem?: any) {
    if (buffSystem) {
      this._buffSystem = buffSystem
    }
    if (characterId && instanceId && config) {
      this.initialize(characterId, instanceId, config)
    }
  }

  /**
   * 获取Buff系统实例（通过构造函数注入）
   */
  private get buffSystem(): any {
    if (!this._buffSystem) {
      console.warn('BuffSystem 未注入，Buff上下文无法正常工作')
    }
    return this._buffSystem
  }

  /**
   * 初始化上下文（用于对象池复用）
   */
  public initialize(characterId: string, instanceId: string, config: BuffConfig, buffSystem?: any): void {
    this.characterId = characterId
    this.instanceId = instanceId
    this.config = config
    this.startTime = Date.now()
    this.variables.clear()
    if (buffSystem) {
      this._buffSystem = buffSystem
    }
  }

  /**
   * 重置上下文（用于对象池归还）
   */
  public reset(): void {
    this.characterId = ''
    this.instanceId = ''
    this.config = {} as BuffConfig
    this.startTime = 0
    this.variables.clear()
    this._buffSystem = null
  }

  /**
   * 获取Buff已持续的时间
   * @returns 已持续时间（毫秒）
   */
  public getElapsedTime(): number {
    return Date.now() - this.startTime
  }

  /**
   * 获取Buff剩余的时间
   * @returns 剩余时间（毫秒），-1表示永久Buff
   */
  public getRemainingTime(): number {
    if (this.config.duration <= 0) {
      return -1
    }
    return Math.max(0, this.config.duration - this.getElapsedTime())
  }

  /**
   * 设置变量
   * @param key 变量键
   * @param value 变量值
   */
  public setVariable(key: string, value: any): void {
    this.variables.set(key, value)
  }

  /**
   * 获取变量
   * @param key 变量键
   * @returns 变量值，不存在则返回undefined
   */
  public getVariable<T>(key: string): T | undefined {
    return this.variables.get(key) as T
  }

  /**
   * 移除变量
   * @param key 变量键
   */
  public removeVariable(key: string): void {
    this.variables.delete(key)
  }

  /**
   * 添加属性修饰符
   * @param attribute 属性名称
   * @param value 修饰值
   * @param type 修饰类型：ADDITIVE（加法）、MULTIPLICATIVE（乘法）、PERCENTAGE（百分比）
   */
  public addModifier(
    attribute: string,
    value: number,
    type: 'ADDITIVE' | 'MULTIPLICATIVE' | 'PERCENTAGE',
  ): void {
    const system = this.buffSystem
    if (!system) {
      console.warn('BuffSystem 未注入，无法添加修饰符')
      return
    }
    const modifierStack = system.getModifierStack(this.characterId)
    modifierStack.addModifier(this.instanceId, attribute as any, value, type)

    // 如果修改的是速度属性，标记需要重新计算回合顺序
    if (attribute === 'SPD') {
      // 这里需要获取到对应的战斗数据并标记速度变化
      // 由于上下文限制，这里暂时只做标记，实际实现需要根据具体架构调整
      console.log(`Speed modifier added for character ${this.characterId}`)
    }
  }

  /**
   * 移除所有修饰符
   */
  public removeModifiers(): void {
    const system = this.buffSystem
    if (!system) {
      console.warn('BuffSystem 未注入，无法移除修饰符')
      return
    }
    const modifierStack = system.getModifierStack(this.characterId)
    modifierStack.removeModifier(this.instanceId)
  }

  /**
   * 获取角色实例
   * @returns 角色实例，不存在则返回undefined
   */
  public getCharacter(): Character | undefined {
    // 这里应该从角色系统获取角色实例
    // 暂时返回 undefined，实际实现需要集成角色系统
    return undefined
  }

  /**
   * 获取属性值
   * @param attribute 属性名称
   * @returns 属性值，获取失败则返回0
   */
  public getAttributeValue(attribute: string): number {
    const character = this.getCharacter()
    if (character) {
      return character.getAttribute(attribute as any)
    }
    return 0
  }

  /**
   * 触发事件
   * @param eventName 事件名称
   * @param data 事件数据（可选）
   */
  public triggerEvent(eventName: string, data?: any): void {
    // 这里应该触发游戏事件系统
    console.log(`Buff event triggered: ${eventName}`, data)
  }
}
