/**
 * 增益效果脚本接口
 * 定义了增益效果的生命周期回调函数,用于实现自定义的增益逻辑
 * @template TParams - 增益效果参数类型,默认为any
 */
export interface IBuffScript<TParams = any> {
  /**
   * 增益效果应用时的回调函数
   * 当增益效果首次添加到角色时调用
   * @param context - 增益效果上下文对象,包含角色、属性等信息
   */
  onApply(context: BuffContext): void

  /**
   * 增益效果移除时的回调函数
   * 当增益效果从角色身上移除时调用
   * @param context - 增益效果上下文对象,包含角色、属性等信息
   */
  onRemove(context: BuffContext): void

  /**
   * 增益效果更新时的回调函数
   * 每帧调用,用于处理持续效果或定时逻辑
   * @param context - 增益效果上下文对象,包含角色、属性等信息
   * @param deltaTime - 距离上一帧的时间增量(毫秒)
   */
  onUpdate(context: BuffContext, deltaTime: number): void

  /**
   * 增益效果刷新时的回调函数
   * 当已有的增益效果被重新施加时调用(如刷新持续时间)
   * @param context - 增益效果上下文对象,包含角色、属性等信息
   */
  onRefresh(context: BuffContext): void

  /**
   * 增益效果的自定义参数
   * 用于存储增益效果特有的配置数据
   */
  params?: TParams
}

/**
 * 叠加规则枚举
 */
export enum StackRule {
  /** 独立叠加：每层独立计算效果 */
  INDEPENDENT = 'independent',
  /** 刷新持续时间：新Buff覆盖旧Buff并重置时间 */
  REFRESH = 'refresh',
  /** 限制层数：达到最大层数后无法继续叠加 */
  LIMITED = 'limited'
}

/**
 * 控制效果类型枚举
 */
export enum ControlType {
  /** 无控制效果 */
  NONE = 'none',
  /** 眩晕：无法进行任何行动 */
  STUN = 'stun',
  /** 沉默：无法使用技能，但可普攻 */
  SILENCE = 'silence',
  /** 冰冻：无法行动，可能有额外效果 */
  FREEZE = 'freeze',
  /** 睡眠：无法行动，受攻击后解除 */
  SLEEP = 'sleep'
}

/**
 * 增益效果配置接口
 * 定义了增益效果的基础属性和约束条件
 */
export interface BuffConfig {
  /**
   * 增益效果唯一标识符
   * 用于在系统中唯一标识一个增益效果
   */
  id: string

  /**
   * 增益效果名称
   * 用于UI显示和日志记录
   */
  name: string

  /**
   * 增益效果描述
   * 详细说明增益效果的作用和机制
   */
  description: string

  /**
   * 增益效果持续时间(回合数)
   * -1表示永久效果,0表示立即移除,正数表示持续回合数
   */
  duration: number

  /**
   * 最大叠加层数
   * 同一增益效果可叠加的最大层数,1表示不可叠加
   */
  maxStacks: number

  /**
   * 冷却时间(回合数)
   * 同一增益效果再次施加所需的冷却回合数
   */
  cooldown: number

  /**
   * 叠加规则
   * 定义Buff的叠加方式
   */
  stackRule: StackRule

  /**
   * 控制效果类型
   * 定义Buff是否为控制效果及其类型
   */
  controlType: ControlType

  /**
   * 控制效果优先级
   * 数值越大优先级越高
   */
  controlPriority: number

  /**
   * 免疫标签
   * 拥有对应标签的角色免疫此Buff
   */
  immuneTags?: string[]

  /**
   * 是否可驱散
   * true表示此Buff可被驱散技能移除
   */
  dispellable?: boolean

  /**
   * 图标路径
   * 用于UI显示Buff图标
   */
  iconPath?: string

  /**
   * 是否为永久效果
   * true表示增益效果不会因时间流逝而消失
   */
  isPermanent?: boolean

  /**
   * 是否为负面效果
   * true表示该增益效果为debuff,会影响角色属性
   */
  isDebuff?: boolean

  /**
   * 增益效果参数配置
   * 用于存储额外的自定义参数,键值对形式
   */
  parameters?: Record<string, any>

  /**
   * 是否为正面效果
   * true表示该增益效果为buff,会增强角色属性
   */
  isPositive?: boolean

  /**
   * 属性修饰符
   * 定义属性加成，使用字符串格式如 "+10"（数值加成）、"+0.05"（百分比加成）、"-0.15"（百分比减成）
   */
  attributes?: Record<string, string>
}

/**
 * 增益效果实例接口
 * 表示一个已应用到角色身上的增益效果实例
 */
export interface BuffInstance<TParams = any> {
  /**
   * 实例唯一标识符
   * 用于唯一标识一个增益效果实例
   */
  id: string

  /**
   * 角色唯一标识符
   * 拥有此增益效果的角色ID
   */
  characterId: string

  /**
   * 增益效果ID
   * 对应BuffConfig中的id
   */
  buffId: string

  /**
   * 增益效果脚本对象
   * 包含增益效果的所有生命周期回调函数
   */
  script: IBuffScript<TParams>

  /**
   * 增益效果上下文对象
   * 包含角色状态、属性等运行时信息
   */
  context: BuffContext

  /**
   * 开始回合
   * 增益效果开始生效的回合数
   */
  startTurn: number

  /**
   * 持续时间(回合数)
   * 当前实例的持续时间,可能与BuffConfig中的duration不同(如被刷新)
   */
  duration: number

  /**
   * 剩余回合数
   * 增益效果还剩余的回合数
   */
  remainingTurns: number

  /**
   * 当前叠加层数
   * 此Buff实例的当前叠加层数
   */
  currentStacks: number

  /**
   * 是否处于激活状态
   * true表示增益效果正在生效,false表示已被暂停或失效
   */
  isActive: boolean
}

/**
 * 增益效果脚本元数据接口
 * 用于描述增益效果脚本的加载状态和路径信息
 */
export interface BuffScriptMetadata {
  /**
   * 增益效果ID
   * 对应BuffConfig中的id
   */
  buffId: string

  /**
   * 脚本文件路径
   * 增益效果脚本文件的相对或绝对路径
   */
  scriptPath: string

  /**
   * 是否已加载
   * true表示脚本已成功加载并初始化
   */
  isLoaded: boolean
}

// ========== 触发器系统类型定义 ==========

/**
 * 触发阶段枚举
 * 定义Buff触发行为的触发时机
 */
export type TriggerPhase =
  | 'ON_BATTLE_START'      // 战斗开始时
  | 'ON_TURN_START'        // 回合开始时（每个参与者的回合开始）
  | 'ON_TURN_END'          // 回合结束时
  | 'ON_ATTACK_BEFORE'     // 攻击前（伤害计算前）
  | 'ON_ATTACK_HIT'        // 攻击命中时（伤害计算后、实际扣血前）
  | 'ON_ATTACK_AFTER'      // 攻击后（伤害结算完成）
  | 'ON_DAMAGE_TAKEN'      // 受到伤害后
  | 'ON_KILL'              // 击杀目标时
  | 'ON_DEATH'             // 自身死亡时
  | 'ON_HEAL_RECEIVED'     // 受到治疗时
  | 'ON_ENERGY_GAINED'     // 获得能量时

/**
 * 触发行为定义
 * 定义Buff在特定阶段触发的行为
 */
export interface TriggerAction {
  /** 触发的阶段 */
  phase: TriggerPhase
  /** 执行脚本ID（如 "deal_damage", "apply_buff", "heal"） */
  scriptId: string
  /** 执行参数（传递给脚本） */
  params?: Record<string, unknown>
  /** 触发概率（0-1），默认1 */
  probability?: number
  /** 冷却回合数（同一Buff实例的内部冷却） */
  cooldown?: number
  /** 最大触发次数（-1表示无限制） */
  maxTriggers?: number
}

/**
 * 触发事件上下文
 * 触发事件发生时的上下文信息
 */
export interface TriggerEventContext {
  /** 触发事件的阶段 */
  phase: TriggerPhase
  /** 事件发生时的战斗实例ID */
  battleId: string
  /** 事件相关的源参与者ID（如攻击者） */
  sourceId?: string
  /** 事件相关的目标参与者ID（如受击者） */
  targetId?: string
  /** 技能ID（如果事件由技能触发） */
  skillId?: string
  /** 伤害/治疗数值 */
  value?: number
  /** 其他自定义数据 */
  extra?: Record<string, unknown>
  /** 当前回合数 */
  currentTurn?: number
  /** 战斗数据（包含所有角色、状态等） */
  battleData?: BattleData
}

/**
 * 触发器运行时状态
 * 追踪Buff实例中每个触发器的运行时状态
 */
export interface TriggerRuntimeState {
  /** 当前冷却回合数 */
  currentCooldown: number
  /** 已触发次数 */
  triggerCount: number
  /** 注册的监听器ID */
  listenerId: string
}
